def solve(inputs: dict) -> float:
    import re
    # Try to extract parameters from inputs
    # Expected keys or parse from a text
    def getnum(keys):
        for k in keys:
            if k in inputs:
                return inputs[k]
        return None
    # Attempt structured keys
    a = getnum(['a', 'add', 'c'])
    m = getnum(['m', 'mod', 'modulus'])
    steps = getnum(['steps', 'n', 'iterations'])
    x = getnum(['x', 'x0', 'start', 'start_x'])
    if a is None or m is None or steps is None or x is None:
        # parse from text
        text = ''
        for v in inputs.values():
            if isinstance(v, str):
                text += ' ' + v
        nums = list(map(int, re.findall(r'-?\d+', text)))
        # pattern: x^2 + A mod M for S steps starting x0
        # from example: 472227(add), 801732(mod), 25(steps), 780756(start)
        if len(nums) >= 4:
            a, m, steps, x = nums[0], nums[1], nums[2], nums[3]
    a = int(a); m = int(m); steps = int(steps); x = int(x)
    for _ in range(steps):
        x = (x*x + a) % m
    return float(x)

