def solve(inputs: dict) -> float:
    import re
    rems = None
    mods = None
    for k in inputs:
        kl = k.lower()
        if 'rem' in kl:
            rems = inputs[k]
        if 'mod' in kl:
            mods = inputs[k]
    if rems is None or mods is None:
        text = ''
        for v in inputs.values():
            if isinstance(v, str):
                text += ' ' + v
        # find bracketed lists
        lists = re.findall(r'\[([^\]]+)\]', text)
        parsed = [list(map(int, re.findall(r'-?\d+', l))) for l in lists]
        if len(parsed) >= 2:
            rems = parsed[0]
            mods = parsed[1]
    rems = [int(r) for r in rems]
    mods = [int(m) for m in mods]
    # CRT
    x = 0
    M = 1
    for m in mods:
        M *= m
    result = 0
    for r, m in zip(rems, mods):
        Mi = M // m
        # inverse of Mi mod m
        inv = pow(Mi, -1, m)
        result += r * Mi * inv
    result %= M
    return float(result)

